stand.css:
.blatt.fl.wk{--unten:22mm;--zahl:13mm}
.wk .fl-fuss{display:flex;justify-content:space-between;align-items:baseline;text-align:left;bottom:8.5mm}
.wk h1{font-size:2em;margin-bottom:.1em}
.wk .teil{margin-top:1.5em}.wk .teil h1{padding-bottom:.3em;border-bottom:.3mm solid var(--messing);margin-bottom:.35em}
.wk h3{margin:1.6em 0 .2em;padding-bottom:.45em;border-bottom:.22mm solid rgba(138,117,69,.55)}
.wk h3.erst{margin-top:0}
.inhalt{max-width:128mm}
.iv{display:flex;align-items:baseline;gap:2.4mm;font-family:var(--serif);font-size:1.12em;color:var(--navy);margin-top:.5em}
.iv i{flex:1;border-bottom:.2mm dotted rgba(138,117,69,.9);transform:translateY(-.25em)}
.iv b{font-weight:400;font-feature-settings:"lnum","tnum";min-width:6mm;white-space:nowrap;text-align:right;color:var(--navy)}
.iv-u{font-family:var(--sans);font-size:.98em;color:#2c3342;padding-left:6mm;margin-top:.22em}
.offene .wn{display:grid;grid-template-columns:30mm 1fr;column-gap:3mm;padding:.72em 0 .76em}
.offene .wn-h b{display:block;font-family:var(--serif);font-weight:400;font-size:1.06em;color:var(--navy)}
.offene .g-n{font-size:1.1em}.offene .g-p{width:22mm;font-size:1.05em}
.offene .g-d{padding-right:36mm;font-size:.95em}
.w{display:grid;grid-template-columns:1fr 38mm calc(var(--zahl)*3 + 6mm);column-gap:3mm;padding:.62em 0;border-bottom:.2mm solid rgba(138,117,69,.3);align-items:start}
.gr .w:last-child,.gr .d:last-child{border-bottom:0}
.w-n{display:flex;gap:3mm;align-items:flex-start;justify-content:space-between}
.w-n>div:first-child>b{display:block;font-family:var(--serif);font-weight:400;font-size:1.1em;line-height:1.3;color:var(--navy)}
.w-n span,.w-t span{display:block;line-height:1.36}
.w-n>div:first-child span{font-size:.94em;color:#4a5060}
.w-a b{color:var(--messing-tief)}
.w-a{flex:none;width:21mm;font-size:.76em;line-height:1.4;color:var(--messing-tief);padding-top:.35em}
.w-t{padding-top:.14em;font-size:.96em}
.w-z{display:grid;grid-template-columns:var(--zahl) calc(var(--zahl) + 6mm) var(--zahl);font-family:var(--serif);color:var(--navy);font-feature-settings:"lnum","tnum";line-height:1.36;padding-top:.1em;font-size:1.02em}
.w-z span{text-align:right;white-space:nowrap}
.w-kopf{border-bottom:0;padding:.9em 0 0;margin-bottom:-1.1em}
.w-kopf>div,.w-kopf .w-z{font-family:var(--sans);font-weight:600;font-size:.8em;letter-spacing:.04em;color:var(--messing-tief)}
.d{display:grid;grid-template-columns:1fr 14mm 11mm 17mm;column-gap:2mm;padding:.34em 0;align-items:baseline;border-bottom:.2mm solid rgba(138,117,69,.22)}
.d>span{text-align:right;font-family:var(--serif);color:var(--navy);font-feature-settings:"lnum","tnum";white-space:nowrap}
.d-n b{font-weight:500;color:var(--tinte);font-size:1.04em}
.d-n span{display:block;font-size:.84em;line-height:1.36;color:#4a5060;max-width:118mm}
.d-nr{font-style:normal;font-family:var(--serif);color:var(--messing-tief);display:inline-block;min-width:1.7em}
.d-kopf{border-bottom:0;padding:.9em 0 0;margin-bottom:-1.1em}
.d-kopf>span{font-family:var(--sans);font-weight:600;font-size:.8em;letter-spacing:.04em;color:var(--messing-tief)}
.d-haus{font-weight:600;font-size:.86em;letter-spacing:.04em;margin:.5em 0 .1em!important}
.wk .gr{margin-top:0}
.wk div.gr:not(:has(h3)){margin-top:1.3em}
.wk .d-kopf+div.gr:not(:has(h3)){margin-top:1.55em;padding-top:.15em;border-top:.3mm solid var(--messing)}
.pr{display:grid;grid-template-columns:1fr 25mm;column-gap:8mm;align-items:start;padding:.85em 0;border-bottom:.2mm solid rgba(138,117,69,.3)}
.pr:last-child{border-bottom:0}
.pr h2{font-size:1.22em;margin:0}
.pr p{font-size:.9em;line-height:1.4}
.pr .pr-o{color:var(--messing-tief);font-size:.95em;margin:.05em 0 .35em}
.pr img{width:25mm;height:25mm;display:block;margin-top:.3em}
